179	
180	bk_err_t bk_int_isr_register(icu_int_src_t source,
181	                             int_group_isr_t handler, void *arg)
182	{
183	  unsigned int index = (unsigned int)source;
184	  irqstate_t flags;
185	  bk_err_t result;
186	  int priority;
187	  int irq;
188	  int ret;
189	
190	  (void)arg; /* The CP CM33 SDK implementation also ignores this argument. */
191	
192	  irq = bk7258_sdk_source_to_irq(source);
193	  if (irq < 0)
194	    {
195	      return BK_ERR_INT_DEVICE_NONE;
196	    }
197	
198	  priority = bk7258_sdk_irq_encode_priority(
199	      bk7258_sdk_irq_default_priority(source));
200	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
201	
202	  /* Registration replaces the previous owner of this source.  Keep the
203	   * line disabled and non-pending until both NuttX dispatch state and
204	   * priority are complete.
205	   */
206	
207	  result = bk7258_sdk_irq_unregister_locked(index, irq);
208	  if (result != BK_OK)
209	    {
210	      goto out;
211	    }
212	
213	  ret = up_prioritize_irq(irq, priority);
214	  if (ret < 0)
215	    {
216	      result = BK_FAIL;
217	      goto out;
218	    }
219	
220	  /* A NULL SDK callback has the same net effect as the vendor CM33 path:
221	   * the previous callback is removed and the interrupt stays disabled.
222	   */
223	
224	  if (handler == NULL)
225	    {
226	      result = BK_OK;
227	      goto out;
228	    }
229	
230	  ret = irq_attach(irq, bk7258_sdk_irq_dispatch, NULL);
231	  if (ret < 0)
232	    {
233	      result = BK_FAIL;
234	      goto out;
235	    }
236	
237	  g_bk7258_sdk_irq_handlers[index] = handler;
238	  UP_DSB();
239	  UP_ISB();
240	  up_enable_irq(irq);
241	  result = BK_OK;
242	
243	out:
244	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
245	  return result;
246	}
