input.new_string:
/* Reject an active callback replacement while the interrupt is enabled.
 * Always allow detach (callback == NULL) so GPIOC_UNREGISTER can release
 * the device for the next user.  On detach, also disable the interrupt
 * and close the route if the device was enabled -- this handles the case
 * where the NuttX GPIO upper-half calls go_attach(NULL) before
 * go_enable(false), and also covers leaked registrations when the
 * application exits without a clean unregister sequence.
 */

if (key->enabled && callback != NULL)
  {
    nxmutex_unlock(&key->lock);
    return -EBUSY;
  }

isr = callback != NULL ? bk7258_gpio_key_isr : NULL;
error = bk_gpio_register_isr(key->pin, isr);
result = bk7258_gpio_result(error);
if (result == OK)
  {
    key->callback = callback;

    if (callback == NULL && key->enabled)
      {
        (void)bk_gpio_disable_interrupt(key->pin);
        (void)bk_gpio_clear_interrupt(key->pin);
        (void)bk7258_gpio_close_route(key);
        key->enabled = false;
      }
  }

nxmutex_unlock(&key->lock);
return result;

