424	        else if (frameNo >= frames->last().no) path = &frames->last().value;
425	        else {
426	            frame = frames->data + _bsearch(frames, frameNo);
427	            if (tvg::equal(frame->no, frameNo)) path = &frame->value;
428	            else if (frame->value.ptsCnt != (frame + 1)->value.ptsCnt) {
429	                path = &frame->value;
430	                TVGLOG("LOTTIE", "Different numbers of points in consecutive frames - interpolation omitted.");
431	            } else {
432	                t = (frameNo - frame->no) / ((frame + 1)->no - frame->no);
433	                if (frame->interpolator) t = frame->interpolator->progress(t);
434	                if (frame->hold) path = &(frame + ((t < 1.0f) ? 0 : 1))->value;
435	                else interpolate = true;
436	            }
437	        }
438	
439	        if (!interpolate) {
440	            if (roundness) {
