442	                    Array<PathCommand> cmds1(path->cmdsCnt);
443	                    Array<Point> pts1(path->ptsCnt);
444	                    roundness->modifyPath(path->cmds, path->cmdsCnt, path->pts, path->ptsCnt, cmds1, pts1, transform);
445	                    return offsetPath->modifyPath(cmds1.data, cmds1.count, pts1.data, pts1.count, cmds, pts);
446	                }
